  messageConcierge: { en: 'Message {c}, your concierge', ta: 'உங்கள் கன்சியர்ஜ் {c} க்குச் செய்தி அனுப்புங்கள்', hi: 'अपने कंसीयर्ज {c} को संदेश भेजें' },
