  madeForTwoNote: { en: 'Made for two. Each partner books their own consents.', ta: 'இருவருக்காக உருவானது. ஒவ்வொரு துணையும் தங்கள் ஒப்புதல்களைத் தாங்களே அளிப்பார்கள்.', hi: 'दो लोगों के लिए बना। हर साथी अपनी सहमति खुद देता है।' },
  outcomeLabel: { en: 'Your named outcome', ta: 'நீங்கள் விரும்பும் விளைவு', hi: 'आपका चुना हुआ परिणाम' },
  outcomeHelp: { en: 'In your words. We measure the ’cation against it.', ta: 'உங்கள் சொற்களில். இதை வைத்தே ’கேஷனை அளக்கிறோம்.', hi: 'आपके शब्दों में। ’केशन को हम इसी पर मापते हैं।' },
  dietLabel: { en: 'Dietary note', ta: 'உணவுக் குறிப்பு', hi: 'खान-पान का नोट' },
