  noPayment: { en: 'No payment now. Payment by Razorpay in INR once your dates are confirmed; GST at {pct} added on the invoice.', ta: 'இப்போது கட்டணம் இல்லை. தேதிகள் உறுதியானதும் Razorpay மூலம் INR இல் கட்டணம்; விலைப்பட்டியலில் {pct} GST சேர்க்கப்படும்.', hi: 'अभी कोई भुगतान नहीं। तारीखें पक्की होने पर Razorpay से INR में भुगतान; बिल में {pct} GST जोड़ा जाएगा।' },
  pricesInclude: { en: 'Prices shown include accommodation, treatments, measures and the ninety days that follow. Specimen pricing.', ta: 'காட்டப்படும் விலைகளில் தங்குமிடம், சிகிச்சைகள், அளவீடுகள், அதைத் தொடரும் தொண்ணூறு நாட்கள் அடங்கும். மாதிரி விலைகள்.', hi: 'दिखाई गई कीमतों में ठहरना, ट्रीटमेंट, माप और उसके बाद के नब्बे दिन शामिल हैं। नमूना कीमतें।' },

  // Circles
  circlesEyebrow: { en: 'Joy Circles · Week {w} of the Practice', ta: 'ஜாய் வட்டங்கள் · பயிற்சியின் வாரம் {w}', hi: 'जॉय सर्कल · अभ्यास का हफ़्ता {w}' },
  circlesTitle: { en: 'The people who hold it *with* you.', ta: 'இதை உங்கள் *கூடவே* சுமக்கும் மனிதர்கள்.', hi: 'वे लोग जो इसे आपके *साथ* थामे रहते हैं।' },
  circlesLead: { en: 'Eight members and a coach, formed at Fairmont before checkout. Thirty minutes every Monday for ninety days. Circles are the strongest single lever on {term}.', ta: 'எட்டு உறுப்பினர்களும் ஒரு கோச்சும், புறப்படும் முன் Fairmont இல் அமைந்த வட்டம். தொண்ணூறு நாட்கள், ஒவ்வொரு திங்களும் முப்பது நிமிடங்கள். {term} கூறை உயர்த்துவதில் வட்டங்களே மிக வலிமையான ஒற்றை வழி.', hi: 'आठ सदस्य और एक कोच, चेक-आउट से पहले Fairmont में बना। नब्बे दिनों तक हर सोमवार तीस मिनट। {term} पर सबसे ज़्यादा असर डालने वाली अकेली चीज़ सर्कल ही है।' },
  nextCall: { en: 'Next call · {name}', ta: 'அடுத்த அழைப்பு · {name}', hi: 'अगली कॉल · {name}' },
