  callMeta: { en: '{date} · {min} minutes · in the app · {open}', ta: '{date} · {min} நிமிடங்கள் · செயலியில் · {open}', hi: '{date} · {min} मिनट · ऐप में · {open}' },
  openNow: { en: 'open now', ta: 'இப்போது திறந்துள்ளது', hi: 'अभी खुला है' },
