  moderates: { en: 'Moderates every call · {name}', ta: 'ஒவ்வொரு அழைப்பையும் வழிநடத்துபவர் · {name}', hi: 'हर कॉल का संचालन · {name}' },
  membersAria: { en: 'Members of your circle, first names only', ta: 'உங்கள் வட்ட உறுப்பினர்கள், முதல் பெயர்கள் மட்டும்', hi: 'आपके सर्कल के सदस्य, सिर्फ़ पहले नाम' },
  joinRoom: { en: 'Join the call room', ta: 'அழைப்பு அறையில் சேருங்கள்', hi: 'कॉल रूम में जुड़ें' },
