  leftLive: { en: 'You left the call. {coach}’s two-line note arrives tonight, and next week’s prompt with it.', ta: 'நீங்கள் அழைப்பிலிருந்து வெளியேறினீர்கள். {coach} அவர்களின் இரண்டு வரிக் குறிப்பு இன்றிரவு வரும்; அதனுடன் அடுத்த வாரக் கேள்வியும்.', hi: 'आप कॉल से निकल गए। {coach} का दो पंक्तियों का नोट आज रात आएगा, और उसके साथ अगले हफ़्ते का सवाल।' },
  leftWaiting: { en: 'Camera and mic checked. The room opens {day} at {time}; {cal}', ta: 'கேமராவும் மைக்கும் சரிபார்க்கப்பட்டன. அறை {day} அன்று {time}க்குத் திறக்கும்; {cal}', hi: 'कैमरा और माइक जाँच लिए गए। कमरा {day} को {time} खुलेगा; {cal}' },
  calWill: { en: 'your calendar will remind you.', ta: 'உங்கள் நாட்காட்டி நினைவூட்டும்.', hi: 'आपका कैलेंडर याद दिला देगा।' },
  calAdd: { en: 'add it to your calendar for a reminder.', ta: 'நினைவூட்டலுக்கு நாட்காட்டியில் சேருங்கள்.', hi: 'याद दिलाने के लिए इसे कैलेंडर में जोड़ लें।' },
  roomEarly: { en: 'The room opens ten minutes early. Camera optional; audio-only is welcome. Test your camera and mic in the waiting room any time.', ta: 'அறை பத்து நிமிடங்கள் முன்பே திறக்கும். கேமரா உங்கள் விருப்பம்; ஒலி மட்டும் போதும். காத்திருப்பு அறையில் எப்போது வேண்டுமானாலும் கேமராவையும் மைக்கையும் சோதிக்கலாம்.', hi: 'कमरा दस मिनट पहले खुल जाता है। कैमरा आपकी मर्ज़ी; सिर्फ़ आवाज़ से जुड़ना भी ठीक है। वेटिंग रूम में कभी भी अपना कैमरा और माइक जाँच लें।' },
  weekPrompt: { en: 'This week’s prompt', ta: 'இந்த வாரக் கேள்வி', hi: 'इस हफ़्ते का सवाल' },
