  formed: { en: 'Formed', ta: 'அமைந்தது', hi: 'बना' },
  joinedOf: { en: 'You have joined {a} of {b}. Missing one is fine; {coach} sends a two-line note.', ta: '{b} அமர்வுகளில் {a} இல் நீங்கள் சேர்ந்தீர்கள். ஒன்றைத் தவறவிட்டால் பரவாயில்லை; {coach} இரண்டு வரிக் குறிப்பு அனுப்புவார்.', hi: 'आप {b} में से {a} में जुड़े हैं। एक छूट जाए तो कोई बात नहीं; {coach} दो पंक्तियों का नोट भेजती हैं।' },
  coachNotes: { en: 'Coach’s notes · no recordings kept', ta: 'கோச்சின் குறிப்புகள் · பதிவுகள் வைக்கப்படுவதில்லை', hi: 'कोच के नोट · कोई रिकॉर्डिंग नहीं रखी जाती' },
  coachNotesLang: { en: '', ta: 'குறிப்புகள் கோச் எழுதியபடியே உள்ளன.', hi: 'नोट वैसे ही हैं जैसे कोच ने लिखे।' },
