  addFeb: { en: 'Add 27 Feb to calendar', ta: '27 பிப் ஐ நாட்காட்டியில் சேருங்கள்', hi: '27 फ़र॰ कैलेंडर में जोड़ें' },
  acceptedNote: { en: 'Accepted. Kavya will see you said yes.', ta: 'ஏற்றுக்கொண்டீர்கள். நீங்கள் சம்மதித்ததை Kavya பார்ப்பார்.', hi: 'स्वीकार किया। Kavya देख पाएँगी कि आपने हाँ कहा।' },
  requestedNote: { en: 'Requested. The lead will write within two days.', ta: 'கோரப்பட்டது. வழிநடத்துபவர் இரண்டு நாட்களுக்குள் எழுதுவார்.', hi: 'अनुरोध भेजा गया। सर्कल चलाने वाले दो दिन में लिखेंगे।' },
  acceptInvitation: { en: 'Accept invitation', ta: 'அழைப்பை ஏற்றுக்கொள்ளுங்கள்', hi: 'निमंत्रण स्वीकारें' },
  askToJoin: { en: 'Ask to join', ta: 'சேரக் கேளுங்கள்', hi: 'जुड़ने का अनुरोध करें' },
  bookedFromCircle: { en: 'Booked from the circle', ta: 'வட்டத்திலிருந்து முன்பதிவு', hi: 'सर्कल से बुक' },
  salonsTitle: { en: 'Connections salons', ta: 'கனெக்ஷன்ஸ் சந்திப்புகள்', hi: 'कनेक्शन्स महफ़िलें' },
  salonsLead: { en: 'Small evenings in your city, hosted, with a single theme. Bring someone from your 15, or come alone and leave with a name.', ta: 'உங்கள் நகரில், ஒரே கருப்பொருளுடன், ஒருவர் நடத்தும் சிறிய மாலைப் பொழுதுகள். உங்கள் 15 பேரில் ஒருவரை அழைத்து வாருங்கள், அல்லது தனியாக வந்து ஒரு புதிய நண்பருடன் செல்லுங்கள்.', hi: 'आपके शहर में छोटी-सी शामें, एक मेज़बान और एक विषय के साथ। अपने 15 लोगों में से किसी को लाइए, या अकेले आइए और एक नया नाम लेकर जाइए।' },
  hostedBy: { en: 'Hosted by {h}', ta: 'நடத்துபவர் {h}', hi: 'मेज़बान {h}' },
  seeInEvents: { en: 'See it in Events', ta: 'நிகழ்வுகளில் பாருங்கள்', hi: 'इवेंट्स में देखें' },
  forTwo: { en: 'For two', ta: 'இருவருக்கு', hi: 'दो के लिए' },
  safeTitle: { en: 'How circles keep you safe', ta: 'வட்டங்கள் உங்களை எப்படிப் பாதுகாக்கின்றன', hi: 'सर्कल आपको कैसे सुरक्षित रखते हैं' },
  safe1: { en: 'First names only, unless you choose to share more.', ta: 'நீங்களாகக் கூடுதலாகப் பகிர்ந்தால் ஒழிய, முதல் பெயர்கள் மட்டும்.', hi: 'सिर्फ़ पहले नाम, जब तक आप खुद ज़्यादा न बताना चाहें।' },
  safe2: { en: 'Recordings are off by default, and never on without everyone agreeing.', ta: 'பதிவு இயல்பாக நிறுத்தத்தில் இருக்கும்; அனைவரும் ஒப்புக்கொள்ளாமல் ஒருபோதும் தொடங்காது.', hi: 'रिकॉर्डिंग शुरू से बंद रहती है, और सबकी सहमति के बिना कभी चालू नहीं होती।' },
  safe3: { en: 'Every call is moderated by your coach.', ta: 'ஒவ்வொரு அழைப்பையும் உங்கள் கோச் வழிநடத்துவார்.', hi: 'हर कॉल का संचालन आपके कोच करते हैं।' },
  safe4: { en: 'Nothing said in the circle enters your record or your Index.', ta: 'வட்டத்தில் பேசப்படும் எதுவும் உங்கள் பதிவிலோ குறியீட்டிலோ சேராது.', hi: 'सर्कल में कही कोई बात आपके रिकॉर्ड या इंडेक्स में नहीं जाती।' },
  safe5: { en: 'Your scores are never shown to the circle. No one is compared.', ta: 'உங்கள் மதிப்பெண்கள் வட்டத்துக்கு ஒருபோதும் காட்டப்படாது. யாரும் ஒப்பிடப்படுவதில்லை.', hi: 'आपके स्कोर सर्कल को कभी नहीं दिखाए जाते। किसी की तुलना नहीं होती।' },
  safe6: { en: 'If something worrying is said, your coach reaches a clinician, not the group.', ta: 'கவலை தரும் ஏதாவது சொல்லப்பட்டால், உங்கள் கோச் குழுவை அல்ல, ஒரு மருத்துவரைத் தொடர்புகொள்வார்.', hi: 'अगर कोई चिंता की बात कही जाए, तो आपके कोच समूह से नहीं, एक चिकित्सक से संपर्क करते हैं।' },
  roomLive: { en: 'Circle call room', ta: 'வட்ட அழைப்பு அறை', hi: 'सर्कल कॉल रूम' },
  roomWait: { en: 'Circle waiting room', ta: 'வட்டக் காத்திருப்பு அறை', hi: 'सर्कल वेटिंग रूम' },
  coachModerated: { en: 'Coach-moderated', ta: 'கோச் வழிநடத்துகிறார்', hi: 'कोच द्वारा संचालित' },
  firstNamesOnly: { en: 'First names only', ta: 'முதல் பெயர்கள் மட்டும்', hi: 'सिर्फ़ पहले नाम' },
  promptLabel: { en: 'Prompt', ta: 'கேள்வி', hi: 'सवाल' },
  waitingRoom: { en: 'Waiting room', ta: 'காத்திருப்பு அறை', hi: 'वेटिंग रूम' },
  waitingOpens: { en: 'Opens {day} · {time}. You can test your camera and mic here.', ta: '{day} · {time}க்குத் திறக்கும். இங்கே உங்கள் கேமராவையும் மைக்கையும் சோதிக்கலாம்.', hi: '{day} · {time} खुलेगा। यहाँ आप अपना कैमरा और माइक जाँच सकते हैं।' },
  previewCall: { en: 'Preview the call (specimen)', ta: 'அழைப்பை முன்னோட்டம் பாருங்கள் (மாதிரி)', hi: 'कॉल की झलक देखें (नमूना)' },
  coachSuffix: { en: ' · coach', ta: ' · கோச்', hi: ' · कोच' },
  camOff: { en: 'Camera off', ta: 'கேமரா அணைப்பில்', hi: 'कैमरा बंद' },
  camWorking: { en: 'Camera working', ta: 'கேமரா இயங்குகிறது', hi: 'कैमरा चल रहा है' },
  handRaised: { en: 'Hand raised', ta: 'கை உயர்த்தப்பட்டது', hi: 'हाथ उठाया' },
