  leaveWaiting: { en: 'Leave the waiting room', ta: 'காத்திருப்பு அறையிலிருந்து வெளியேறு', hi: 'वेटिंग रूम से निकलें' },

  // Events
  eventsEyebrow: { en: 'Events', ta: 'நிகழ்வுகள்', hi: 'इवेंट्स' },
  eventsTitle: { en: 'Come together. Leave *measured*.', ta: 'ஒன்றுகூடுங்கள். *அளக்கப்பட்டுச்* செல்லுங்கள்.', hi: 'साथ आइए। *माप* के साथ लौटिए।' },
  eventsLead: { en: 'AIWO Joyspan at New Year, Joyspan Sessions in cities and Houses, and Connections salons. Every guest leaves with an Index and a Day-90 date.', ta: 'புத்தாண்டில் AIWO Joyspan, நகரங்களிலும் ஹவுஸ்களிலும் ஜாய்ஸ்பான் அமர்வுகள், கனெக்ஷன்ஸ் சந்திப்புகள். ஒவ்வொரு விருந்தினரும் ஒரு குறியீட்டுடனும் நாள்-90 தேதியுடனும் செல்கிறார்.', hi: 'नए साल पर AIWO Joyspan, शहरों और हाउस में जॉयस्पैन सेशन, और कनेक्शन्स महफ़िलें। हर मेहमान एक इंडेक्स और दिन-90 की तारीख लेकर जाता है।' },
  yourPasses: { en: 'Your passes · {n} upcoming', ta: 'உங்கள் பாஸ்கள் · {n} வரவிருக்கின்றன', hi: 'आपके पास · {n} आने वाले' },
  tabUpcoming: { en: 'Upcoming', ta: 'வரவிருப்பவை', hi: 'आने वाले' },
  tabPast: { en: 'Past', ta: 'கடந்தவை', hi: 'पिछले' },
  attended: { en: 'Attended', ta: 'கலந்துகொண்டீர்கள்', hi: 'शामिल हुए' },
