  entry: { en: 'Entry', ta: 'நுழைவு', hi: 'प्रवेश' },
  seat: { en: 'Seat', ta: 'இருக்கை', hi: 'सीट' },
  confirmCancelAria: { en: 'Confirm cancellation', ta: 'ரத்தை உறுதிசெய்யுங்கள்', hi: 'रद्द करने की पुष्टि करें' },
  cancelQ: { en: 'Cancel this booking?', ta: 'இந்த முன்பதிவை ரத்து செய்யவா?', hi: 'यह बुकिंग रद्द करें?' },
