  membershipRenews: { en: '{m} membership · renews 5 Jan 2028', ta: '{m} உறுப்பினர் நிலை · 5 ஜன 2028 அன்று புதுப்பிக்கப்படும்', hi: '{m} सदस्यता · 5 जन॰ 2028 को नवीनीकरण' },
