  chartAria: { en: 'Joy moments a day: {list}. Week 4 so far.', ta: 'ஒரு நாளுக்கான மகிழ்ச்சித் தருணங்கள்: {list}. வாரம் 4 இதுவரை.', hi: 'रोज़ के खुशी के पल: {list}। हफ़्ता 4 अब तक।' },
