  nfWeekTitle: { en: 'That week is not part of the Practice.', ta: 'அந்த வாரம் பயிற்சியின் பகுதி அல்ல.', hi: 'वह हफ़्ता अभ्यास का हिस्सा नहीं है।' },
  nfWeekLead: { en: 'The Practice runs for eight weeks.', ta: 'பயிற்சி எட்டு வாரங்கள் நடக்கும்.', hi: 'अभ्यास आठ हफ़्ते चलता है।' },
  nfWeekEmpty: { en: 'Choose a week from one to eight', ta: 'ஒன்று முதல் எட்டு வரை ஒரு வாரத்தைத் தேர்ந்தெடுங்கள்', hi: 'एक से आठ तक कोई हफ़्ता चुनें' },
  nfWeekBody: { en: 'Each week has five minutes of audio, a science note and one practice.', ta: 'ஒவ்வொரு வாரத்திலும் ஐந்து நிமிட ஒலிப்பதிவு, ஒரு அறிவியல் குறிப்பு, ஒரு பயிற்சி உண்டு.', hi: 'हर हफ़्ते में पाँच मिनट का ऑडियो, एक विज्ञान नोट और एक अभ्यास है।' },
