  reflHint: { en: 'Never shared with your circle or coach unless you choose. VIVA does not read it.', ta: 'நீங்கள் விரும்பினால் ஒழிய உங்கள் வட்டத்துடனோ கோச்சுடனோ ஒருபோதும் பகிரப்படாது. VIVA இதைப் படிப்பதில்லை.', hi: 'जब तक आप न चाहें, यह आपके सर्कल या कोच से कभी साझा नहीं होता। VIVA इसे नहीं पढ़ता।' },
  saveReflection: { en: 'Save reflection', ta: 'சிந்தனைக் குறிப்பைச் சேமி', hi: 'चिंतन सहेजें' },
  savedAt: { en: 'Saved at {t}', ta: '{t} க்குச் சேமிக்கப்பட்டது', hi: '{t} पर सहेजा गया' },
