// ─── Helpers ──────────────────────────────────────────────────────────────

type NumVal = { n: string | number }
export type RichVal = string | number | NumVal | ReactNode

const isNum = (v: unknown): v is NumVal => !!v && typeof v === 'object' && !isValidElement(v) && 'n' in (v as object)

/**
 * A translated string as React nodes: {var} placeholders take strings, numbers
 * (wrapped in the Mono `num` span), { n } (also Mono) or elements; *text* is <em>.
 */
export function rich(s: string, vars?: Record<string, RichVal>): ReactNode {
  const parts = s.split(/(\{\w+\}|\*[^*]+\*)/g).filter((p) => p !== '')
  const nodes = parts.map((p): ReactNode => {
    if (p.length > 2 && p.startsWith('*') && p.endsWith('*')) return createElement('em', null, rich(p.slice(1, -1), vars))
    const m = /^\{(\w+)\}$/.exec(p)
    if (m && vars && m[1] in vars) {
      const v = vars[m[1]]
      if (typeof v === 'number') return createElement('span', { className: 'num' }, v)
      if (isNum(v)) return createElement('span', { className: 'num' }, v.n)
      return v as ReactNode
    }
    return p
  })
  return createElement(Fragment, null, ...nodes)
}

const LOCALE: Record<Lang, string> = { en: 'en-GB', ta: 'ta-IN', hi: 'hi-IN' }
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const DAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']

/** Month and weekday abbreviations in specimen date strings (“Sat 20 Feb 2027 · 10:00”); digits stay Latin. */
function localDates(lang: Lang, s: string) {
  if (lang === 'en') return s
  const loc = LOCALE[lang]
  return s
    .replace(/\b(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\b(?= \d{4})/g, (m) => new Date(2027, MONTHS.indexOf(m), 1).toLocaleDateString(loc, { month: 'short' }))
    .replace(/\b(Sun|Mon|Tue|Wed|Thu|Fri|Sat)\b(?= \d)/g, (d) => new Date(2027, 0, 3 + DAYS.indexOf(d)).toLocaleDateString(loc, { weekday: 'short' }))
}

/** Data text in the member's language; segments joined by “ · ” are looked up one by one. */
export function txFor(lang: Lang, s: string, vars?: Record<string, string | number>) {
  if (lang === 'en' || !s) return fill(s, vars)
  const i = lang === 'ta' ? 0 : 1
  const hit = DATA[s]
  if (hit) return fill(hit[i], vars)
  if (s.includes(' · ')) return s.split(' · ').map((p) => DATA[p]?.[i] ?? localDates(lang, p)).join(' · ')
  return localDates(lang, fill(s, vars))
}

/** Everything a journey screen needs to speak the member's language. */
export function useJ() {
  const { lang } = useApp()
  const t = useDict(JOURNEY)
  const term = useTermText()
  const r = (key: JourneyKey, vars?: Record<string, RichVal>) => rich(t(key), vars)
  const tx = (s: string, vars?: Record<string, string | number>) => txFor(lang, s, vars)
  const termLabel = (k: TermKey | 'ALL') => (k === 'ALL' ? t('allSix') : term.name(k))
  const status = (s: string) => t(s === 'FY28' ? 'st_FY28' : s === 'NEW' ? 'st_NEW' : 'st_LIVE')
  /** “7 pm” in the member's language, digits Latin. */
  const clock = (h: number, m = 0) => t('clock', { t: `${h % 12 || 12}${m ? `.${String(m).padStart(2, '0')}` : ''}`, ap: t(h < 12 ? 'am' : 'pm') })
  return { lang, en: lang === 'en', t, r, tx, term, termLabel, status, clock, locale: LOCALE[lang] }
}
